PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE members (tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','assistant')), PRIMARY KEY(tenant_id,user_id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE classes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, subject TEXT NOT NULL DEFAULT '', fee INTEGER NOT NULL DEFAULT 0 CHECK(fee>=0), archived INTEGER NOT NULL DEFAULT 0, UNIQUE(tenant_id,id));
CREATE TABLE students (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', guardian TEXT NOT NULL DEFAULT '', archived INTEGER NOT NULL DEFAULT 0, UNIQUE(tenant_id,id));
CREATE TABLE enrollments (tenant_id TEXT NOT NULL, class_id TEXT NOT NULL, student_id TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,class_id,student_id), FOREIGN KEY(tenant_id,class_id) REFERENCES classes(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE lessons (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, class_id TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL CHECK(ends_at>starts_at), topic TEXT NOT NULL DEFAULT '', UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,class_id) REFERENCES classes(tenant_id,id));
CREATE TABLE attendance (tenant_id TEXT NOT NULL, lesson_id TEXT NOT NULL, student_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')), PRIMARY KEY(tenant_id,lesson_id,student_id), FOREIGN KEY(tenant_id,lesson_id) REFERENCES lessons(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE invoices (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, student_id TEXT NOT NULL, description TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), due_date TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE payments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, invoice_id TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), request_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,request_key), FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id));
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, resource_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX classes_tenant ON classes(tenant_id);
CREATE INDEX students_tenant ON students(tenant_id);
CREATE INDEX lessons_tenant_date ON lessons(tenant_id,starts_at);
CREATE INDEX invoices_tenant ON invoices(tenant_id);
CREATE INDEX payments_invoice ON payments(tenant_id,invoice_id);
CREATE INDEX audit_tenant ON audit_logs(tenant_id,created_at);
